
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_zpbesol_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_zpbesol", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-7.322811302160796e-02, -7.220826676757275e-02, -7.074401015473125e-02, -6.864323182302558e-02, -6.563258790210841e-02, -6.132671303193503e-02, -5.519751738246573e-02, -4.659530227496533e-02, -3.512470398128173e-02, -2.342258033369894e-02, -3.073482221010794e-02, -4.429771680165042e-02, -4.900238869559077e-02, -3.762859939945752e-02, -2.509454493093936e-02, -1.926634161089262e-02, -1.858072934049322e-02, -8.247096722486975e-03, -2.295605187484643e-03, -3.268687243322624e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


